from collections import deque
from typing import List

def fastestSFCommute(grid: List[str], times: List[int], costs: List[int]) -> List[int]:
    R, C = len(grid), len(grid[0])
    cells = {grid[i][j]: (i, j) for i in range(R) for j in range(C) if grid[i][j] in "SD"}
    start, dest = cells['S'], cells['D']
    best = None
    for mode in range(1, 5):
        ok = {'S', 'D', str(mode)}
        dist = {start: 0}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in dist and grid[nr][nc] in ok:
                    dist[(nr, nc)] = dist[(r, c)] + 1
                    q.append((nr, nc))
        if dest in dist:
            s = dist[dest]
            cand = [s * times[mode - 1], s * costs[mode - 1], mode]
            if best is None or cand[:2] < best[:2]:
                best = cand
    return [-1, -1, -1] if best is None else [best[2], best[0], best[1]]
